const MAX_CALLS = 6;
const MAX_ESTIMATED_COST = 0.12;
let calls = 0;
let estimatedCost = 0;
function assertBudget(nextCost) {
  if (++calls > MAX_CALLS) throw new Error("call limit exceeded");
  estimatedCost += nextCost;
  if (estimatedCost > MAX_ESTIMATED_COST) throw new Error("cost limit exceeded");
}
